-- =============================================================
--  Versión 5: nomencladores con la estructura de gestion_adm (prest_nomenclador*)
--  y órdenes de laboratorio y de estudios.
--
--  NOMENCLADORES
--  Mismas tablas y columnas que gestion_adm: un nomenclador, sus capítulos, sus códigos
--  (el código es texto: los ceros a la izquierda distinguen 001 de 0001), y los valores
--  aparte, por vigencia (un código dura años, su valor un mes).
--  Lo que estaba cargado en las tablas de la versión 2 (nomencladores, nomenclador_practicas)
--  se pasa a las nuevas con ids corridos (+100 los nomencladores, +100000 los códigos) para
--  dejar libres los ids de origen de la carga de gestion_adm: PMO 1, Bioquímicas 2, PAMI 5,
--  OBSBA 6 y NBU 7. A la carga se le recuperaron la Ñ y los acentos que el CSV de origen
--  traía como «?».
--
--  Se aplica sola al abrir la app (ver inc/migraciones.php).
-- =============================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS prest_nomenclador (
  id          INT          NOT NULL AUTO_INCREMENT,
  nombre      VARCHAR(60)  NOT NULL,
  importador  VARCHAR(20)  NULL DEFAULT NULL COMMENT 'Lector de PDF (gestion_adm). NULL = carga manual o CSV.',
  activo      TINYINT(1)   NOT NULL DEFAULT 1,
  creado      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  actualizado DATETIME     NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_prest_nomenclador_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Nomencladores (PMO, NBU, PAMI...)';

CREATE TABLE IF NOT EXISTS prest_nomenclador_capitulo (
  id             INT          NOT NULL AUTO_INCREMENT,
  id_nomenclador INT          NOT NULL,
  id_padre       INT          NULL DEFAULT NULL,
  nivel          TINYINT      NOT NULL COMMENT '1 sección, 2 capítulo, 3 subgrupo',
  clave          VARCHAR(255) NOT NULL,
  sigla          VARCHAR(10)  NULL DEFAULT NULL,
  nombre         VARCHAR(200) NOT NULL,
  orden          INT          NOT NULL DEFAULT 0,
  creado         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  actualizado    DATETIME     NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_prest_nom_capitulo_clave (id_nomenclador, clave),
  KEY ix_prest_nom_capitulo_padre (id_padre),
  CONSTRAINT fk_prest_nom_capitulo_nomenclador FOREIGN KEY (id_nomenclador) REFERENCES prest_nomenclador (id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_prest_nom_capitulo_padre FOREIGN KEY (id_padre) REFERENCES prest_nomenclador_capitulo (id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Secciones, capítulos y subgrupos de un nomenclador';

CREATE TABLE IF NOT EXISTS prest_nomenclador_codigo (
  id             INT          NOT NULL AUTO_INCREMENT,
  id_nomenclador INT          NOT NULL,
  id_capitulo    INT          NULL DEFAULT NULL,
  codigo         VARCHAR(20)  NOT NULL COMMENT 'Texto: los ceros a la izquierda distinguen (001 / 0001) y hay alfanuméricos',
  nombre         VARCHAR(500) NOT NULL,
  activo         TINYINT(1)   NOT NULL DEFAULT 1,
  creado         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  actualizado    DATETIME     NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_prest_nom_codigo (id_nomenclador, codigo),
  KEY ix_prest_nom_codigo_nombre (id_nomenclador, nombre(100)),
  KEY ix_prest_nom_codigo_capitulo (id_capitulo),
  CONSTRAINT fk_prest_nom_codigo_nomenclador FOREIGN KEY (id_nomenclador) REFERENCES prest_nomenclador (id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_prest_nom_codigo_capitulo FOREIGN KEY (id_capitulo) REFERENCES prest_nomenclador_capitulo (id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Códigos de práctica de cada nomenclador';

CREATE TABLE IF NOT EXISTS prest_nomenclador_vigencia (
  id             INT          NOT NULL AUTO_INCREMENT,
  id_nomenclador INT          NOT NULL,
  desde          DATE         NOT NULL,
  hasta          DATE         NULL DEFAULT NULL COMMENT 'NULL = sin fecha de fin',
  documento      VARCHAR(60)  NULL DEFAULT NULL,
  archivo        VARCHAR(255) NULL DEFAULT NULL,
  sha1           CHAR(40)     NULL DEFAULT NULL,
  codigos        INT          NOT NULL DEFAULT 0,
  observaciones  TEXT         NULL,
  usuario_id     INT          NULL DEFAULT NULL,
  creado         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_prest_nom_vigencia_desde (id_nomenclador, desde),
  CONSTRAINT fk_prest_nom_vigencia_nomenclador FOREIGN KEY (id_nomenclador) REFERENCES prest_nomenclador (id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ediciones de un nomenclador con su período de vigencia';

CREATE TABLE IF NOT EXISTS prest_nomenclador_valor (
  id               INT              NOT NULL AUTO_INCREMENT,
  id_vigencia      INT              NOT NULL,
  id_codigo        INT              NOT NULL,
  importe          DECIMAL(14,2)    NOT NULL,
  dias_internacion TINYINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_prest_nom_valor (id_vigencia, id_codigo),
  KEY ix_prest_nom_valor_codigo (id_codigo, id_vigencia),
  CONSTRAINT fk_prest_nom_valor_vigencia FOREIGN KEY (id_vigencia) REFERENCES prest_nomenclador_vigencia (id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_prest_nom_valor_codigo FOREIGN KEY (id_codigo) REFERENCES prest_nomenclador_codigo (id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Importe de cada código en cada vigencia';

-- Código de cada prestación del centro en cada nomenclador
CREATE TABLE IF NOT EXISTS prestacion_codigo (
  prestacion_id INT NOT NULL,
  codigo_id     INT NOT NULL,
  PRIMARY KEY (prestacion_id, codigo_id),
  KEY ix_prestacion_codigo_codigo (codigo_id),
  CONSTRAINT fk_prestacion_codigo_prestacion FOREIGN KEY (prestacion_id) REFERENCES prestaciones (id) ON DELETE CASCADE,
  CONSTRAINT fk_prestacion_codigo_codigo FOREIGN KEY (codigo_id) REFERENCES prest_nomenclador_codigo (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- Lo cargado en la versión 2 pasa a las tablas nuevas ----------
INSERT INTO prest_nomenclador (id, nombre, activo)
SELECT id + 100, LEFT(nombre, 60), activo FROM nomencladores;

INSERT INTO prest_nomenclador_capitulo (id_nomenclador, nivel, clave, nombre)
SELECT DISTINCT nomenclador_id + 100, 2, LEFT(capitulo, 255), LEFT(capitulo, 200)
  FROM nomenclador_practicas WHERE capitulo IS NOT NULL AND capitulo <> '';

INSERT INTO prest_nomenclador_codigo (id, id_nomenclador, id_capitulo, codigo, nombre, activo)
SELECT p.id + 100000, p.nomenclador_id + 100, k.id, p.codigo, p.descripcion, p.activo
  FROM nomenclador_practicas p
  LEFT JOIN prest_nomenclador_capitulo k ON k.id_nomenclador = p.nomenclador_id + 100 AND k.clave = LEFT(p.capitulo, 255);

INSERT INTO prest_nomenclador_vigencia (id_nomenclador, desde, documento, codigos, observaciones)
SELECT nomenclador_id + 100, CURDATE(), 'Valores anteriores', COUNT(*), 'Valores cargados antes de la versión 5 del sistema.'
  FROM nomenclador_practicas WHERE valor IS NOT NULL GROUP BY nomenclador_id;

INSERT INTO prest_nomenclador_valor (id_vigencia, id_codigo, importe)
SELECT g.id, p.id + 100000, p.valor
  FROM nomenclador_practicas p
  JOIN prest_nomenclador_vigencia g ON g.id_nomenclador = p.nomenclador_id + 100 AND g.documento = 'Valores anteriores'
 WHERE p.valor IS NOT NULL;

INSERT INTO prestacion_codigo (prestacion_id, codigo_id)
SELECT prestacion_id, practica_id + 100000 FROM prestacion_practicas;

ALTER TABLE obras_sociales DROP FOREIGN KEY fk_os_nom;
UPDATE obras_sociales SET nomenclador_id = nomenclador_id + 100 WHERE nomenclador_id IS NOT NULL;
UPDATE configuracion SET valor = CAST(valor AS UNSIGNED) + 100 WHERE clave = 'nomenclador_defecto' AND valor REGEXP '^[1-9][0-9]*$';
DROP TABLE prestacion_practicas;
DROP TABLE nomenclador_practicas;
DROP TABLE nomencladores;
ALTER TABLE obras_sociales ADD CONSTRAINT fk_os_nom FOREIGN KEY (nomenclador_id) REFERENCES prest_nomenclador (id) ON DELETE SET NULL;

-- ---------- Órdenes de laboratorio y de estudios ----------
CREATE TABLE IF NOT EXISTS ordenes (
  id                  INT AUTO_INCREMENT PRIMARY KEY,
  numero              INT NULL,
  tipo                ENUM('laboratorio','estudios') NOT NULL DEFAULT 'estudios',
  paciente_id         INT NOT NULL,
  profesional_id      INT NOT NULL,
  turno_id            INT NULL,
  fecha               DATE NOT NULL,
  obra_social_id      INT NULL,
  obra_social_nombre  VARCHAR(100) NULL,
  rnas                CHAR(6) NULL,
  plan                VARCHAR(60) NULL,
  nro_afiliado        VARCHAR(40) NULL,
  nomenclador_id      INT NULL,
  nomenclador_nombre  VARCHAR(60) NULL,
  cie10_codigo        VARCHAR(7) NULL,
  diagnostico         VARCHAR(255) NULL,
  indicaciones        TEXT NULL COMMENT 'Preparación, ayuno, observaciones para el prestador',
  urgente             TINYINT(1) NOT NULL DEFAULT 0,
  estado              ENUM('borrador','firmada','anulada') NOT NULL DEFAULT 'borrador',
  firmada_en          DATETIME NULL,
  hash                CHAR(64) NULL,
  codigo_verificacion CHAR(10) NULL,
  cuir                VARCHAR(40) NULL,
  plataforma          VARCHAR(80) NULL,
  motivo_anulacion    VARCHAR(255) NULL,
  anulada_en          DATETIME NULL,
  usuario_id          INT NULL,
  creado              DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  actualizado         DATETIME NULL,
  UNIQUE KEY uk_orden_numero (numero),
  UNIQUE KEY uk_orden_codigo (codigo_verificacion),
  KEY idx_orden_paciente (paciente_id, fecha),
  KEY idx_orden_prof (profesional_id, fecha),
  CONSTRAINT fk_orden_pac FOREIGN KEY (paciente_id) REFERENCES pacientes(id),
  CONSTRAINT fk_orden_prof FOREIGN KEY (profesional_id) REFERENCES profesionales(id),
  CONSTRAINT fk_orden_turno FOREIGN KEY (turno_id) REFERENCES turnos(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS orden_items (
  id          INT AUTO_INCREMENT PRIMARY KEY,
  orden_id    INT NOT NULL,
  orden       SMALLINT NOT NULL DEFAULT 1,
  codigo_id   INT NULL,
  codigo      VARCHAR(20) NULL,
  descripcion VARCHAR(500) NOT NULL,
  cantidad    TINYINT NOT NULL DEFAULT 1,
  observacion VARCHAR(255) NULL,
  KEY idx_oi_orden (orden_id, orden),
  CONSTRAINT fk_oi_orden FOREIGN KEY (orden_id) REFERENCES ordenes(id) ON DELETE CASCADE,
  CONSTRAINT fk_oi_codigo FOREIGN KEY (codigo_id) REFERENCES prest_nomenclador_codigo(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

